new file mode 100644
index 0000000..8e78470
--- /dev/null
+++ b/runtime/executors/claude/src/executor-audit.test.ts
@@ -0,0 +1,270 @@
+/**
+ * Integration tests for Claude executor audit building.
+ *
+ * The auditable data is constructed inside the processResultJson closure in main(),
+ * which is not directly testable. These tests verify the building logic by
+ * mirroring the same construction pattern. A failing test here means the
+ * executor_audit shape has drifted from what the orchestrator expects.
+ *
+ * Covers:
+ *   1. Full audit with token_usage + RAG + GitNexus queries
+ *   2. Token-only audit (no MCP calls)
+ *   3. MCP-only audit (no token data)
+ *   4. Empty audit — no data at all
+ *   5. HermesExecutorAudit minimum shape (always present, minimum {})
+ */
+
+import { describe, it, expect } from "vitest";
+import type {
+  ExecutorAudit,
+  ClaudeExecutorAudit,
+  HermesExecutorAudit,
+} from "@workflow/runtime-abi";
+
+// ── Helpers mirroring processResultJson logic ─────────────────────────────────
+
+interface TokenUsage {
+  input: number;
+  output: number;
+  model: string;
+  cost_usd: number;
+}
+
+interface RagQueryRecord {
+  query: string;
+  result_length: number;
+}
+
+interface GitnexusQueryRecord {
+  tool: string;
+  arguments: Record<string, unknown>;
+  result_length: number;
+}
+
+function buildClaudeExecutorAudit(
+  tokenUsage: TokenUsage | undefined,
+  ragQueries: RagQueryRecord[],
+  gitnexusQueries: GitnexusQueryRecord[],
+): ExecutorAudit | undefined {
+  const claudeAudit: ClaudeExecutorAudit = {
+    ...(tokenUsage !== undefined && {
+      token_usage: {
+        input: tokenUsage.input,
+        output: tokenUsage.output,
+        model: tokenUsage.model,
+      },
+    }),
+    ...((ragQueries.length > 0 || gitnexusQueries.length > 0) && {
+      mcp_usage: {
+        rag_queries: ragQueries,
+        gitnexus_queries: gitnexusQueries,
+      },
+    }),
+  };
+
+  const executorAudit: ExecutorAudit = {
+    ...(tokenUsage !== undefined && { cost_usd: tokenUsage.cost_usd }),
+    ...(Object.keys(claudeAudit).length > 0 && { claude: claudeAudit }),
+  };
+
+  if (Object.keys(executorAudit).length > 0) {
+    return executorAudit;
+  }
+  return undefined;
+}
+
+function buildHermesExecutorAudit(turnsCount: number | undefined): ExecutorAudit {
+  const hermesAudit: HermesExecutorAudit =
+    turnsCount !== undefined && turnsCount > 0 ? { turns: turnsCount } : {};
+  return { hermes: hermesAudit };
+}
+
+// ── Claude executor — full audit ──────────────────────────────────────────────
+
+describe("buildClaudeExecutorAudit", () => {
+  const tokenUsage: TokenUsage = {
+    input: 15000,
+    output: 2500,
+    model: "claude-sonnet-4-6",
+    cost_usd: 0.75,
+  };
+
+  const ragQueries: RagQueryRecord[] = [
+    { query: "what is TypeScript", result_length: 3 },
+    { query: "how to use vitest", result_length: 2 },
+  ];
+
+  const gitnexusQueries: GitnexusQueryRecord[] = [
+    { tool: "query", arguments: { symbol: "extractRagQueries" }, result_length: 45 },
+    { tool: "impact", arguments: { symbol: "dispatchReviewResult" }, result_length: 120 },
+  ];
+
+  it("builds full audit with token_usage, RAG, and GitNexus queries", () => {
+    const audit = buildClaudeExecutorAudit(tokenUsage, ragQueries, gitnexusQueries);
+
+    expect(audit).toBeDefined();
+    expect(audit!.cost_usd).toBe(0.75);
+    expect(audit!.claude).toBeDefined();
+    expect(audit!.claude!.token_usage).toEqual({
+      input: 15000,
+      output: 2500,
+      model: "claude-sonnet-4-6",
+    });
+    expect(audit!.claude!.mcp_usage).toBeDefined();
+    expect(audit!.claude!.mcp_usage!.rag_queries).toHaveLength(2);
+    expect(audit!.claude!.mcp_usage!.rag_queries[0]!.query).toBe("what is TypeScript");
+    expect(audit!.claude!.mcp_usage!.gitnexus_queries).toHaveLength(2);
+    expect(audit!.claude!.mcp_usage!.gitnexus_queries[0]!.tool).toBe("query");
+  });
+
+  it("builds token-only audit when no MCP calls were made", () => {
+    const audit = buildClaudeExecutorAudit(tokenUsage, [], []);
+
+    expect(audit).toBeDefined();
+    expect(audit!.cost_usd).toBe(0.75);
+    expect(audit!.claude).toBeDefined();
+    expect(audit!.claude!.token_usage).toBeDefined();
+    expect(audit!.claude!.mcp_usage).toBeUndefined();
+  });
+
+  it("builds MCP-only audit when no token data is available", () => {
+    const audit = buildClaudeExecutorAudit(undefined, ragQueries, gitnexusQueries);
+
+    expect(audit).toBeDefined();
+    expect(audit!.cost_usd).toBeUndefined();
+    expect(audit!.claude).toBeDefined();
+    expect(audit!.claude!.token_usage).toBeUndefined();
+    expect(audit!.claude!.mcp_usage).toBeDefined();
+    expect(audit!.claude!.mcp_usage!.rag_queries).toHaveLength(2);
+  });
+
+  it("returns undefined when no data is available at all", () => {
+    const audit = buildClaudeExecutorAudit(undefined, [], []);
+
+    expect(audit).toBeUndefined();
+  });
+
+  it("includes mcp_usage when only RAG queries exist (no GitNexus)", () => {
+    const audit = buildClaudeExecutorAudit(undefined, ragQueries, []);
+
+    expect(audit).toBeDefined();
+    expect(audit!.claude!.mcp_usage).toBeDefined();
+    expect(audit!.claude!.mcp_usage!.rag_queries).toHaveLength(2);
+    expect(audit!.claude!.mcp_usage!.gitnexus_queries).toHaveLength(0);
+  });
+
+  it("includes mcp_usage when only GitNexus queries exist (no RAG)", () => {
+    const audit = buildClaudeExecutorAudit(undefined, [], gitnexusQueries);
+
+    expect(audit).toBeDefined();
+    expect(audit!.claude!.mcp_usage).toBeDefined();
+    expect(audit!.claude!.mcp_usage!.rag_queries).toHaveLength(0);
+    expect(audit!.claude!.mcp_usage!.gitnexus_queries).toHaveLength(2);
+  });
+
+  it("mcp_usage fields match @workflow/runtime-abi ClaudeExecutorAudit type", () => {
+    const audit = buildClaudeExecutorAudit(tokenUsage, ragQueries, gitnexusQueries)!;
+
+    // Type-level check: the audit object must be assignable to ExecutorAudit
+    const _typed: ExecutorAudit = audit;
+
+    // Verify the shape matches the ABI type definition
+    expect(typeof audit.cost_usd).toBe("number");
+    expect(audit.claude).toBeDefined();
+    if (audit.claude!.token_usage) {
+      expect(typeof audit.claude!.token_usage.input).toBe("number");
+      expect(typeof audit.claude!.token_usage.output).toBe("number");
+    }
+    if (audit.claude!.mcp_usage) {
+      expect(Array.isArray(audit.claude!.mcp_usage.rag_queries)).toBe(true);
+      expect(Array.isArray(audit.claude!.mcp_usage.gitnexus_queries)).toBe(true);
+      for (const rq of audit.claude!.mcp_usage.rag_queries) {
+        expect(typeof rq.query).toBe("string");
+        expect(typeof rq.result_length).toBe("number");
+      }
+      for (const gq of audit.claude!.mcp_usage.gitnexus_queries) {
+        expect(typeof gq.tool).toBe("string");
+        expect(typeof gq.arguments).toBe("object");
+        expect(typeof gq.result_length).toBe("number");
+      }
+    }
+  });
+});
+
+// ── Hermes executor — always present audit ────────────────────────────────────
+
+describe("buildHermesExecutorAudit", () => {
+  it("always returns at minimum { hermes: {} }", () => {
+    const audit = buildHermesExecutorAudit(undefined);
+    expect(audit).toEqual({ hermes: {} });
+  });
+
+  it("returns { hermes: {} } when turns is 0", () => {
+    const audit = buildHermesExecutorAudit(0);
+    expect(audit).toEqual({ hermes: {} });
+  });
+
+  it("returns { hermes: { turns: N } } when turns > 0", () => {
+    const audit = buildHermesExecutorAudit(42);
+    expect(audit).toEqual({ hermes: { turns: 42 } });
+  });
+
+  it("hermes field matches @workflow/runtime-abi HermesExecutorAudit type", () => {
+    const audit = buildHermesExecutorAudit(15);
+    const _typed: ExecutorAudit = audit;
+    expect(audit.hermes).toBeDefined();
+    expect(typeof audit.hermes!.turns).toBe("number");
+    expect(audit.hermes!.turns).toBe(15);
+  });
+
+  it("hermes field is empty object when no turns detected (minimum shape)", () => {
+    const audit = buildHermesExecutorAudit(undefined);
+    expect(audit.hermes).toEqual({});
+    expect(Object.keys(audit.hermes!)).toHaveLength(0);
+  });
+});
+
+// ── Combined audit — both executor kinds present ──────────────────────────────
+
+describe("Combined ExecutorAudit shape", () => {
+  it("can carry both claude and hermes audit data", () => {
+    const combined: ExecutorAudit = {
+      cost_usd: 0.75,
+      claude: {
+        token_usage: { input: 1000, output: 500, model: "claude-sonnet-4-6" },
+        mcp_usage: {
+          rag_queries: [{ query: "test", result_length: 1 }],
+          gitnexus_queries: [],
+        },
+      },
+      hermes: { turns: 20 },
+    };
+
+    expect(combined.cost_usd).toBe(0.75);
+    expect(combined.claude!.token_usage!.input).toBe(1000);
+    expect(combined.hermes!.turns).toBe(20);
+  });
+
+  it("supports hermes-only audit (no claude data)", () => {
+    const hermesOnly: ExecutorAudit = {
+      hermes: { turns: 5 },
+    };
+
+    expect(hermesOnly.claude).toBeUndefined();
+    expect(hermesOnly.hermes).toBeDefined();
+    expect(hermesOnly.hermes!.turns).toBe(5);
+  });
+
+  it("supports claude-only audit (no hermes data)", () => {
+    const claudeOnly: ExecutorAudit = {
+      cost_usd: 0.5,
+      claude: {
+        token_usage: { input: 2000, output: 800, model: "claude-sonnet-4-6" },
+      },
+    };
+
+    expect(claudeOnly.cost_usd).toBe(0.5);
+    expect(claudeOnly.claude).toBeDefined();
+    expect(claudeOnly.hermes).toBeUndefined();
+  });
+});
