index 0000000..1fdad09
--- /dev/null
+++ b/runtime/orchestrator/tests/max-turns-env.test.ts
@@ -0,0 +1,177 @@
+/**
+ * Static verification that MAX_TURNS is not injected by the orchestrator into
+ * any executor extraEnv object.
+ *
+ * Post-T5: MAX_TURNS was removed from the orchestrator's extraEnv construction
+ * in both main.ts (buildAndSubmitExecutor) and pr/dispatch-reviewer.ts.
+ * Executors now inherit MAX_TURNS from the orchestrator's own process.env
+ * (via SubProcessAdapter's ...process.env spread), so operators set it on the
+ * orchestrator service in docker-compose.
+ *
+ * This test is a static grep check: a false positive from a comment or
+ * documentation string would be a false failure. The test looks for
+ * `MAX_TURNS` being used as an object key in a value context
+ * (i.e. `MAX_TURNS:` or `"MAX_TURNS":` or `'MAX_TURNS':`).
+ */
+
+import { describe, it, expect } from "vitest";
+import { readFileSync, readdirSync, statSync } from "node:fs";

