+  /MAX_TURNS \/\/ executor turn budget/,
+  /MAX_TURNS is executor-read/,
+];
+
+function walkDir(dir: string): string[] {
+  const files: string[] = [];
+  for (const entry of readdirSync(dir, { withFileTypes: true })) {
+    const full = join(dir, entry.name);
+    if (entry.isDirectory() && entry.name !== "node_modules" && entry.name !== "dist") {
+      files.push(...walkDir(full));
+    } else if (entry.isFile() && /\.(ts|js|json|yaml|yml)$/.test(entry.name)) {
+      files.push(full);
+    }
+  }
+  return files;
+}
+
+describe("MAX_TURNS — not in orchestrator extraEnv construction", () => {
+  const orchestratorSrc = resolve(import.meta.dirname, "..", "src");
+
+  it("MAX_TURNS is not used as an object key in orchestrator source files", () => {
+    const files = walkDir(orchestratorSrc);
+    const violations: string[] = [];
+
+    for (const file of files) {
+      const rel = relative(orchestratorSrc, file);
+      try {
+        const content = readFileSync(file, "utf-8");
+        const lines = content.split("\n");
+
+        for (let i = 0; i < lines.length; i++) {
+          const line = lines[i]!;
+
+          // Match `MAX_TURNS:` or `"MAX_TURNS":` or `'MAX_TURNS':` as an object key
+          // (property assignment, not a comment or documentation string)
+          const keyMatch = line.match(/(?:^|\s|\()(?:'MAX_TURNS'|"MAX_TURNS"|MAX_TURNS)\s*:/);
+          if (!keyMatch) continue;
+
+          // Skip lines that are inside comments
+          const trimmed = line.trim();
+          if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*")) continue;
+
+          // Skip lines inside JSDoc or block comments (heuristic: line has * and is within a comment)
+          // Re-read surrounding lines if needed — simple heuristic for now
+          const fullLine = line;
+
+          // Check if this is in a documentation string (CLAUDE.md description in comment)
+          // These are expected to mention MAX_TURNS for documentation purposes
+          const isDocComment =
+            (i > 0 && lines[i - 1]?.trim().startsWith("*")) ||
+            (i > 0 && lines[i - 1]?.trim().startsWith("//")) ||
+            fullLine.includes("*   MAX_TURNS");
+
+          if (isDocComment) continue;
+
+          violations.push(`${rel}:${i + 1}: ${fullLine.trim()}`);
+        }
+      } catch {
+        // skip unreadable files
+      }
+    }
+
+    expect(violations).toEqual([]);
+  });
+
