+    // Verify the Claude executor reads MAX_TURNS from process.env (correct post-T5 behavior)
+    const executorsSrc = resolve(import.meta.dirname, "..", "..", "executors");
+    const claudeIndexPath = join(executorsSrc, "claude", "src", "index.ts");
+    const content = readFileSync(claudeIndexPath, "utf-8");
+
+    // MAX_TURNS should be read from process.env (inherited from orchestrator)
+    expect(content).toContain("process.env.MAX_TURNS");
+
+    // The comment in the Claude executor docs is expected
+    // MAX_TURNS appears in the doc block at the top
+    const docBlockLines = content.split("\n").filter(
+      (l) => l.trim().startsWith("*") && l.includes("MAX_TURNS"),
+    );
+    expect(docBlockLines.length).toBeGreaterThanOrEqual(1);
+  });
+
+  it("HERMES_MAX_TURNS is the Hermes-specific env var (not plain MAX_TURNS)", () => {
+    // Verify HERMES_MAX_TURNS is correctly used for Hermes executor
