+    const content = readFileSync(factoryPath, "utf-8");
+
+    // HERMES_MAX_TURNS should be in resolveExecutorEnv for hermes type
+    expect(content).toContain("HERMES_MAX_TURNS");
+
+    // Verify hermesMaxTurns is read from HERMES_MAX_TURNS env
+    const mainPath = join(orchestratorSrc, "main.ts");
+    const mainContent = readFileSync(mainPath, "utf-8");
+    expect(mainContent).toContain("HERMES_MAX_TURNS");
+  });
+
+  it("findEligibleTasks uses status-based guard (no log-scan for reviewer_started)", () => {
+    // Verify the log-scan predicate is absent from findReviewableTasks
+    const matchPath = join(orchestratorSrc, "eligibility", "match.ts");
+    const content = readFileSync(matchPath, "utf-8");
+
+    // The old log-scan pattern: `t.log[t.log.length - 1]?.action !== "reviewer_started"`
+    // should NOT be present in findReviewableTasks
+    expect(content).not.toMatch(/log\[.*length.*-.*1.*\]/);
+  });
+
+  it("dispatchReviewer claim guard uses status check, not log-scan", () => {
+    // Verify dispatchReviewer uses task.status === "reviewing" instead of log-scan
+    const dispatchReviewerPath = join(orchestratorSrc, "pr", "dispatch-reviewer.ts");
+    const content = readFileSync(dispatchReviewerPath, "utf-8");
+
+    // Should have the reviewing status check
+    expect(content).toContain('task.status === "reviewing"');
+
+    // Should NOT scan the log for reviewer_started
+    const logScanPattern = /lastEntry\??\.action\s*===\s*"reviewer_started"/;
+    expect(logScanPattern.test(content)).toBe(false);
+  });
+
+  it("claimFixTask guard uses status check, not log-scan", () => {
+    // Verify claimFixTask uses task.status === "in_progress" instead of log-scan
+    const claimFixPath = join(orchestratorSrc, "task", "claim-fix.ts");
+    const content = readFileSync(claimFixPath, "utf-8");
+
+    // Should have the in_progress status check
+    expect(content).toContain('task.status === "in_progress"');
+
+    // Should NOT scan the log for fix_started
+    const logScanPattern = /last\??\.action\s*===\s*"fix_started"/;
+    expect(logScanPattern.test(content)).toBe(false);
+  });
+});
+
+describe("MAX_TURNS — executor env inheritance", () => {
+  it("Claude executor doc lists MAX_TURNS as an inherited (Day-1) env var", () => {
+    const executorsSrc = resolve(import.meta.dirname, "..", "..", "executors");
+    const claudeIndexPath = join(executorsSrc, "claude", "src", "index.ts");
+    const content = readFileSync(claudeIndexPath, "utf-8");
+
+    // The Day-1 extras section should mention MAX_TURNS
+    expect(content).toContain("MAX_TURNS          — max claude CLI turns");
+  });
+
+  it("Hermes executor uses HERMES_MAX_TURNS (not MAX_TURNS)", () => {
+    const executorsSrc = resolve(import.meta.dirname, "..", "..", "executors");
+    const hermesIndexPath = join(executorsSrc, "hermes", "src", "index.ts");
