    type PartialResult = { terminal_status: string; pr_url?: string; blocked_reason?: string };

    const cases: Array<{ result: PartialResult; expected: boolean }> = [
      { result: { terminal_status: "in_review", pr_url: "https://github.com/a/b/pull/1" }, expected: true },
