    const lines = [
      JSON.stringify({ type: "turn", index: 1 }),
      "plain text line",
      JSON.stringify({ type: "assistant_message", content: "hello" }),
      JSON.stringify({ type: "tool_call", tool: "bash" }),
      JSON.stringify({ type: "other_event", data: "ignored" }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({ turns: 3 });
  });

  it("ignores non-turn JSON events", () => {
    const lines = [
      JSON.stringify({ type: "phase_start", phase: 1 }),
      JSON.stringify({ type: "phase_done", phase: 1 }),
      JSON.stringify({ type: "executor_fatal", details: "error" }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({});
  });

  it("returns empty object when stdout has only invalid JSON lines", () => {
    const stdout = "{ not valid json }\n{ also bad\nnot json at all";
    expect(buildHermesAudit(stdout)).toEqual({});
  });

  it("counts iteration events", () => {
    const lines = [
      JSON.stringify({ type: "iteration", step: 1 }),
      JSON.stringify({ type: "iteration", step: 2 }),
    ].join("\n");
    expect(buildHermesAudit(lines)).toEqual({ turns: 2 });
  });
});

// ── Phase 6 no-changes path ───────────────────────────────────────────────────

describe("Phase 6 no-changes path", () => {
  it("commitAndPush returns false on clean tree with no branch (no remote check)", () => {
    // Contract: false return triggers blocked:no_changes in the wrapper fallback path.
    // When no branch is provided, only the working-tree dirtiness is checked —
    // no origin/<branch>..HEAD comparison is made.
    const tmpDir = join(tmpdir(), `clean-tree-${Date.now()}`);
    mkdirSync(tmpDir, { recursive: true });
    try {
      execSync(`git init "${tmpDir}"`, { stdio: "pipe" });
      execSync(`git -C "${tmpDir}" config user.email "t@t.com"`, { stdio: "pipe" });
      execSync(`git -C "${tmpDir}" config user.name "T"`, { stdio: "pipe" });
      writeFileSync(join(tmpDir, "init.txt"), "init\n");
      execSync(`git -C "${tmpDir}" add -A`, { stdio: "pipe" });
      execSync(`git -C "${tmpDir}" commit -m "init"`, { stdio: "pipe" });

      const result = commitAndPush({
        repoDir: tmpDir,
        taskId: "T4",
        featureId: "feat",
        sshKeyPath: undefined,
        gitAuthorEmail: "t@t.com",
        gitAuthorName: "T",
      });
      expect(result).toBe(false);
    } finally {
      rmSync(tmpDir, { recursive: true, force: true });
    }
  });
});

